from playwright.sync_api import sync_playwright
from pathlib import Path
import json
root=Path('/mnt/data/eduhub_admin_payments')
source=(root/'eduhub-admin-payments-standalone.html').read_text()
results={'responsive':[],'interactions':[],'errors':[],'geometry':{}}
with sync_playwright() as pw:
 browser=pw.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage','--disable-web-security'])
 for width in (1440,834,390,320):
  page=browser.new_page(viewport={'width':width,'height':900},device_scale_factor=1)
  errors=[];page.on('pageerror',lambda err: errors.append(str(err)))
  page.set_content(source,wait_until='load',timeout=30000);page.wait_for_timeout(140)
  g=page.evaluate('''() => {const q=s=>{let e=document.querySelector(s);if(!e)return null;const r=e.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}};return {docWidth:document.documentElement.scrollWidth,pageHeight:document.documentElement.scrollHeight,topbar:q('.admin-topbar'),intro:q('.page-intro'),metrics:q('.payment-metrics'),note:q('.demo-note'),panel:q('.payments-panel'),filters:q('.payment-filters'),list:q('.payments-list'),item:q('.payment-item'),footer:q('.admin-footer')}}''')
  results['geometry'][str(width)]=g
  if g['docWidth']>width: results['errors'].append(f'horizontal overflow {width}: {g["docWidth"]}')
  if errors: results['errors'].append(f'JavaScript width={width}: {errors}')
  page.screenshot(path=str(root/f'previews/{width}px.png'),full_page=True,animations='disabled')
  results['responsive'].append({'width':width,'height':g['pageHeight'],'horizontalOverflow':g['docWidth']>width,'javascriptErrors':errors})
  page.close()
 page=browser.new_page(viewport={'width':1440,'height':900},device_scale_factor=1)
 errors=[];page.on('pageerror',lambda err:errors.append(str(err)))
 page.set_content(source,wait_until='load',timeout=30000)
 def test(name,fn):
  try:fn();results['interactions'].append({'name':name,'pass':True})
  except Exception as e:results['interactions'].append({'name':name,'pass':False,'error':str(e)[:400]})
 def eq(a,b):assert a==b,repr((a,b))
 def check_sample():eq(page.locator('.payment-item:visible').count(),6);eq(page.locator('#totalCompleted').inner_text(),'982');eq(page.locator('#totalRefunded').inner_text(),'12')
 test('six exact Figma rows and totals',check_sample)
 def search_student():page.locator('#paymentSearch').fill('Warda');eq(page.locator('.payment-item:visible').count(),1);eq(page.locator('.payment-item:visible').first.get_attribute('data-id'),'PAY-2026-1048')
 test('search by student',search_student)
 def search_id():page.locator('#paymentSearch').fill('PAY-2026-1046');eq(page.locator('.payment-item:visible').count(),1)
 test('search by payment ID',search_id)
 def search_course():page.locator('#paymentSearch').fill('HTML & CSS');eq(page.locator('.payment-item:visible').count(),2)
 test('search by course',search_course)
 def no_results():page.locator('#paymentSearch').fill('something-never-in-demo');eq(page.locator('#noResults').is_visible(),True)
 test('no results state',no_results)
 def clear_filters():page.locator('#resetFilters').click();eq(page.locator('.payment-item:visible').count(),6)
 test('clear filters',clear_filters)
 def filter_status():page.locator('#statusFilter').select_option('pending');eq(page.locator('.payment-item:visible').count(),1)
 test('status pending filter',filter_status)
 test('status refunded filter',lambda:(page.locator('#statusFilter').select_option('refunded'),eq(page.locator('.payment-item:visible').count(),1)))
 test('status completed filter',lambda:(page.locator('#statusFilter').select_option('completed'),eq(page.locator('.payment-item:visible').count(),3)))
 test('date exact filter',lambda:(page.locator('#statusFilter').select_option('all'),page.locator('#dateFilter').select_option('2026-10-28'),eq(page.locator('.payment-item:visible').count(),2)))
 def range_start():page.locator('#dateFilter').select_option('custom');eq(page.locator('#dateBackdrop').is_visible(),True)
 test('custom date dialog',range_start)
 def range_invalid():page.locator('#dateFrom').fill('2026-10-30');page.locator('#dateTo').fill('2026-10-01');page.locator('#applyDateDialog').click();eq(page.locator('#dateError').is_visible(),True)
 test('invalid custom date error',range_invalid)
 def range_apply():page.locator('#dateFrom').fill('2026-10-27');page.locator('#dateTo').fill('2026-10-29');page.locator('#applyDateDialog').click();eq(page.locator('.payment-item:visible').count(),4)
 test('custom date range applies',range_apply)
 def reset_custom():page.locator('#dateFilter').select_option('custom');page.locator('#resetDateDialog').click();eq(page.locator('#dateFilter').input_value(),'all')
 test('reset custom date',reset_custom)
 def global_search():page.locator('#workspaceSearch').fill('Nour Adel');eq(page.locator('.payment-item:visible').count(),1)
 test('workspace header search',global_search)
 def pagination():page.locator('#workspaceSearch').fill('');page.locator('#nextPage').click();eq(page.locator('#unavailablePage').is_visible(),True);page.locator('#returnFirstPage').click();eq(page.locator('.payment-item:visible').count(),6)
 test('pagination never fabricates records',pagination)
 def detail_click():page.locator('[data-view="PAY-2026-1047"]').click();eq(page.locator('#paymentBackdrop').is_visible(),True);eq(page.locator('#dialogTitle').inner_text(),'Payment Details · PAY-2026-1047');eq(page.locator('#confirmRefund').is_visible(),False)
 test('pending transaction is view-only',detail_click)
 test('escape closes payment details',lambda:(page.keyboard.press('Escape'),eq(page.locator('#paymentBackdrop').is_visible(),False)))
 def refund_open():page.locator('[data-refund="PAY-2026-1048"]').click();eq(page.locator('#refundExtra').is_visible(),True);eq(page.locator('#confirmRefund').is_visible(),True)
 test('eligible Warda refund confirmation',refund_open)
 page.screenshot(path=str(root/'previews/refund-confirmation.png'),animations='disabled')
 test('cancel refund does not update',lambda:(page.locator('#cancelPaymentDialog').click(),eq(page.locator('#totalRefunded').inner_text(),'12')))
 def refund_apply():page.locator('[data-refund="PAY-2026-1048"]').click();page.locator('#confirmRefund').click();eq(page.locator('#totalRefunded').inner_text(),'13');eq(page.locator('#totalCompleted').inner_text(),'981');eq(page.locator('[data-id="PAY-2026-1048"] .payment-badge').inner_text(),'Refunded');eq(page.locator('[data-refund="PAY-2026-1048"]').count(),0)
 test('refund updates existing record only',refund_apply)
 page.screenshot(path=str(root/'previews/refunded-result.png'),animations='disabled')
 def now_ineligible():page.locator('[data-view="PAY-2026-1048"]').click();eq(page.locator('#confirmRefund').is_visible(),False);page.locator('#cancelPaymentDialog').click()
 test('refunded record no longer eligible',now_ineligible)
 test('notification dropdown works',lambda:(page.locator('#notificationToggle').click(),eq(page.locator('#notificationMenu').is_visible(),True)))
 test('account dropdown closes notification',lambda:(page.locator('#accountToggle').click(),eq(page.locator('#notificationMenu').is_visible(),False),eq(page.locator('#accountMenu').is_visible(),True)))
 results['errors']+=errors;page.close()
 mobile=browser.new_page(viewport={'width':390,'height':844});mobile.set_content(source)
 test('mobile admin drawer',lambda:(mobile.locator('#openMobileNav').click(),eq(mobile.locator('#adminSidebar').evaluate("el=>el.classList.contains('is-open')"),True)))
 test('mobile Escape closes drawer',lambda:(mobile.keyboard.press('Escape'),eq(mobile.locator('#adminSidebar').evaluate("el=>el.classList.contains('is-open')"),False)))
 test('mobile workspace search expands',lambda:(mobile.locator('#openMobileSearch').click(),eq(mobile.locator('#searchContainer').evaluate("el=>el.classList.contains('is-open')"),True)))
 browser.close()
(root/'validation-results.json').write_text(json.dumps(results,indent=2))
print(json.dumps(results,indent=2)[:20000])
